param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot out/staging};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs);Add-Type -Path (Join-Path $PSScriptRoot NativeChatTest.cs)
$root=Join-Path $ProjectRoot ('artifacts/text-reactions-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$desktop=$null;$service=$null;$provider=$null;$checks=0;$env:HIBERNATION_SESSION_KEY='text-reaction-fixture';$env:TEMP=Join-Path $BuildRoot tmp;$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name){$end=[DateTime]::UtcNow.AddSeconds(25);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 30};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer text-reaction-fixture'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function Widget{(Api '/api/capabilities').plugins.Where({$_.id-eq'widget'})[0].current}
function Drag{$position=Widget;$x=[int]($position.x*($screen.right-112)+56);$y=[int]($position.y*($screen.bottom-112)+56);$null=[ChatWindowTest]::Send($widget,0x201,0,($y-shl16)-bor$x);$null=[ChatWindowTest]::Send($widget,0x200,1,($y-shl16)-bor($x+24));$null=[ChatWindowTest]::Send($widget,0x202,0,($y-shl16)-bor($x+24))}
try{
 $providerRoot=Join-Path $root provider;$provider=Start-Process (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root provider.log) -RedirectStandardError (Join-Path $root provider-error.log);Wait-For {Test-Path (Join-Path $providerRoot port)} 'provider';$fixture='http://127.0.0.1:'+(Get-Content (Join-Path $providerRoot port))
 $batch=@{version=1;reactions=@('先让我看看这次落脚的地方，脚下的空白有一点不同。','刚才移过来的时候，有一小段路没有走完。','我把尾巴收起来一点，先停在这个位置。','这样的位置也可以，等我自己站稳以后再走。','还好，这一下没有把我刚才看的那一点弄丢。','我先记住脚边的位置，不急着继续走过去。')|ForEach-Object {@{text=$_;animation='curious'}}};@{nonce=[Guid]::NewGuid().ToString('N');responses=@(@{response=$batch})}|ConvertTo-Json -Depth 20|Set-Content (Join-Path $providerRoot plan.json) -Encoding utf8
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.frontend=@{startupAnimation=$false;reducedMotion=$true};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.plugins=@{widget=@{enabled=$true;roam=$false;reactionCacheEnabled=$true;reactionCooldownMs=250;reactionProbability=1;charactersPerSecond=5;pageHoldSeconds=1}};$cfg.review=@{enabled=$false};$cfg.profiles+=@{id='fixture';label='Local synthetic role';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';timeoutMs=5000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 30|Set-Content (Join-Path $root config.json) -Encoding utf8
 $desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),(Join-Path $root config.json),(Join-Path $root ready.json),$ProjectRoot);$service=$desktop.Child;Wait-For {if($service.HasExited){throw 'private reaction process exited'};Test-Path (Join-Path $root ready.json)} 'ready';$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $root ready.json) -Raw|ConvertFrom-Json).port)
 $widget=$desktop.Find('HibernationDinosaurOverlay');Check ($widget-ne[IntPtr]::Zero) 'only the isolated desktop widget receives test mouse messages';[ChatWindowTest]::UseWindowCoordinates($widget);$screen=New-Object ChatWindowTest+Rect;$null=[ChatWindowTest]::GetClientRect($widget,[ref]$screen)
 $null=Api '/api/model' @{id='fixture'};$null=Api '/api/reactions/refill' @{};Wait-For {(Api '/api/reactions/status').available-eq6} 'text candidates ready';Check (@((Api '/api/capabilities').plugins|Where-Object {$_.id-eq'tts'-and$_.enabled}).Count-eq0) 'text reactions work with voice plugin absent'
 Drag;Wait-For {(Api '/api/reactions/status').available-eq5-and(Widget).bubble_in_progress} 'first text reaction';$first=(Widget).bubble_reply_id;Start-Sleep -Milliseconds 350;Drag;Start-Sleep -Milliseconds 450;Check ((Api '/api/reactions/status').available-eq5-and(Widget).bubble_reply_id-eq$first) 'short cooldown never cuts off a text-only reaction';Wait-For {!(Widget).bubble_in_progress} 'first text reading interval finishes';Check ((Api '/api/reactions/status').available-eq5) 'ignored drag is never replayed after reading finishes'
 Drag;Wait-For {(Api '/api/reactions/status').available-eq4} 'next text reaction';Check ((Widget).bubble_reply_id-ne$first) 'a later eligible drag consumes a different candidate';Wait-For {!(Widget).bubble_in_progress} 'second text reading interval finishes'
 $null=Api '/api/plugin/test' @{tool='widget.say';args=@{text='这一小段还没有读完。';seconds=3}};Wait-For {(Api '/api/plugin/result').state-eq'succeeded'} 'manual text bubble';$remaining=(Api '/api/reactions/status').available;Drag;Start-Sleep -Milliseconds 400;Check ((Api '/api/reactions/status').available-eq$remaining) 'drag also respects an existing non-voice plugin bubble';Check ((Api '/api/chat').messages.Count-eq0-and!(Api '/api/chat').busy) 'ambient text stays outside conversation and model queue'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'private text reaction process closes cleanly';@{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content (Join-Path $root acceptance.json);Write-Output "Text reactions passed: $checks checks. Evidence: $root"
}finally{if($service-and!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{}};if($desktop){$desktop.Dispose()};if($provider-and!$provider.HasExited){$provider.Kill();$provider.WaitForExit(5000)|Out-Null}}
